"""MANUS teleop manager: teleop/calibration services gate MANUS processes.

On launch this node exposes teleop plus start/open/fist/clear calibration services.
Commands use CODE:IP (same as IO exo), e.g. 1:192.168.0.103.

Pipeline: one shared manus_data_publisher plus up to one retarget process per
hand side (left / right). ``1:IP_L`` then ``2:IP_R`` keeps both retargets alive.
"""

from __future__ import annotations

import os
import signal
import subprocess
import threading
import time
from dataclasses import dataclass, field
from pathlib import Path

import rclpy
from ament_index_python.packages import PackageNotFoundError, get_package_share_directory
from rclpy.callback_groups import ReentrantCallbackGroup
from rclpy.executors import MultiThreadedExecutor
from rclpy.node import Node

from apex_hand_teleop.manus_teleop_controller import (
    DEFAULT_FOLLOW_TOPIC_SUFFIX,
    DEFAULT_GET_CONNECTION_INFO_SERVICE,
    DEFAULT_MANUS_TELEOP_SERVICE,
    BoundSession,
    COMMAND_HELP,
    normalize_side,
    parse_teleop_command,
    resolve_follow_topic,
)

try:
    from manus_ros2_msgs.msg import ManusGlove
    from manus_ros2_msgs.srv import (
        CalibrateGloveTheta,
        ClearGloveThetaCalibration,
        RecordGloveFistCalibration,
    )
    from rysen_apexhand_msgs.srv import ManusCalibration, StartTeleop
except ImportError:  # pragma: no cover
    ManusGlove = None  # type: ignore
    CalibrateGloveTheta = None  # type: ignore
    ClearGloveThetaCalibration = None  # type: ignore
    RecordGloveFistCalibration = None  # type: ignore
    ManusCalibration = None  # type: ignore
    StartTeleop = None  # type: ignore

ROLE_MANUS = "manus"
ROLE_LEFT = "left"
ROLE_RIGHT = "right"
RETARGET_ROLES = (ROLE_LEFT, ROLE_RIGHT)

DEFAULT_START_CALIBRATION_SERVICE = "/rysen/apexhand/start_manus_calibration"
DEFAULT_OPEN_CALIBRATION_SERVICE = "/rysen/apexhand/calibrate_manus_open"
DEFAULT_FIST_CALIBRATION_SERVICE = "/rysen/apexhand/calibrate_manus_fist"
DEFAULT_CLEAR_CALIBRATION_SERVICE = "/rysen/apexhand/clear_manus_calibration"
DEFAULT_THETA_CALIBRATION_SERVICE = "/manus/calibrate_glove_theta"
DEFAULT_CLEAR_THETA_CALIBRATION_SERVICE = "/manus/clear_glove_theta_calibration"
DEFAULT_RECORD_FIST_CALIBRATION_SERVICE = "/manus/record_glove_fist_calibration"

CALIBRATION_WAIT_OPEN = "wait_open"
CALIBRATION_WAIT_FIST = "wait_fist"
CALIBRATION_COMPLETE = "complete"


@dataclass
class ManagerState:
    sessions: dict[str, BoundSession] = field(default_factory=dict)
    forwarding: bool = False
    glove_mode: str = "none"
    last_glove_stamp: dict[str, float] = field(default_factory=dict)
    # side -> raw /manus_glove_* topic observed carrying that side
    side_to_glove_topic: dict[str, str] = field(default_factory=dict)
    last_raw_side: str = ""
    no_hand_streak: int = 0
    connected_ips: set[str] = field(default_factory=set)
    # Sides that have successfully armed follow_publish.
    armed_sides: set[str] = field(default_factory=set)
    calibration_stage: dict[str, str] = field(default_factory=dict)
    external_manus: bool = False

    @property
    def active(self) -> bool:
        return bool(self.sessions)


class ManusTeleopManager(Node):
    def __init__(self) -> None:
        super().__init__("manus_teleop_manager")

        if StartTeleop is None:
            raise RuntimeError(
                "rysen_apexhand_msgs not available; build/source it first."
            )

        self.declare_parameter("teleop_service_name", DEFAULT_MANUS_TELEOP_SERVICE)
        self.declare_parameter(
            "get_connection_info_service", DEFAULT_GET_CONNECTION_INFO_SERVICE
        )
        self.declare_parameter("follow_topic_suffix", DEFAULT_FOLLOW_TOPIC_SUFFIX)
        self.declare_parameter("glove_activity_timeout_sec", 0.5)
        self.declare_parameter("connection_poll_period_sec", 1.0)
        # 0 = never auto-stop when ApexHand is not in get_connection_info.
        self.declare_parameter("no_hand_auto_stop_count", 0)
        self.declare_parameter(
            "glove_activity_topics", ["/manus_glove_0", "/manus_glove_1"]
        )

        # Child process params (forwarded when spawning retarget / manus).
        self.declare_parameter("glove_topic", "/manus_glove_0")
        self.declare_parameter("calibration_file", "")
        self.declare_parameter("runtime_calibration_file", "")
        self.declare_parameter("calibration_glove_id", "")
        self.declare_parameter("model_xml", "")
        self.declare_parameter("rate_hz", 500.0)
        self.declare_parameter("enable_viewer", False)
        self.declare_parameter("apexhand_ip", "192.168.0.102")
        self.declare_parameter("apexhand_command_filter_window_size", 10)
        self.declare_parameter("startup_ready_timeout_sec", 15.0)
        self.declare_parameter(
            "start_manus_calibration_service_name",
            DEFAULT_START_CALIBRATION_SERVICE,
        )
        self.declare_parameter(
            "open_manus_calibration_service_name",
            DEFAULT_OPEN_CALIBRATION_SERVICE,
        )
        self.declare_parameter(
            "fist_manus_calibration_service_name",
            DEFAULT_FIST_CALIBRATION_SERVICE,
        )
        self.declare_parameter(
            "clear_manus_calibration_service_name",
            DEFAULT_CLEAR_CALIBRATION_SERVICE,
        )
        self.declare_parameter(
            "manus_theta_calibration_service_name",
            DEFAULT_THETA_CALIBRATION_SERVICE,
        )
        self.declare_parameter(
            "clear_manus_theta_calibration_service_name",
            DEFAULT_CLEAR_THETA_CALIBRATION_SERVICE,
        )
        self.declare_parameter(
            "record_manus_fist_calibration_service_name",
            DEFAULT_RECORD_FIST_CALIBRATION_SERVICE,
        )

        self._cb_group = ReentrantCallbackGroup()
        self._lock = threading.Lock()
        self._state = ManagerState()
        # Role -> process: "manus" | "left" | "right"
        self._procs: dict[str, subprocess.Popen] = {}
        # side -> (ip, opposition_enabled, glove_topic) used for last retarget spawn
        self._retarget_spawn_key: dict[str, tuple[str, bool, str]] = {}
        self._conn_request_inflight = False
        self._activity_subs = []

        self._glove_activity_timeout_sec = float(
            self.get_parameter("glove_activity_timeout_sec").value
        )
        self._no_hand_auto_stop_count = max(
            1, int(self.get_parameter("no_hand_auto_stop_count").value)
        )
        self._startup_ready_timeout_sec = max(
            1.0, float(self.get_parameter("startup_ready_timeout_sec").value)
        )
        self._follow_topic_suffix = str(
            self.get_parameter("follow_topic_suffix").value
        ).strip() or DEFAULT_FOLLOW_TOPIC_SUFFIX

        service_name = str(self.get_parameter("teleop_service_name").value).strip()

        self._srv = self.create_service(
            StartTeleop,
            service_name,
            self._on_start_teleop,
            callback_group=self._cb_group,
        )
        self._calibration_srvs = []
        self._theta_calibration_client = None
        self._clear_theta_calibration_client = None
        self._fist_calibration_client = None
        if (
            ManusCalibration is not None
            and CalibrateGloveTheta is not None
            and ClearGloveThetaCalibration is not None
            and RecordGloveFistCalibration is not None
        ):
            self._calibration_srvs = [
                self.create_service(
                    ManusCalibration,
                    str(
                        self.get_parameter(
                            "start_manus_calibration_service_name"
                        ).value
                    ),
                    self._on_start_manus_calibration,
                    callback_group=self._cb_group,
                ),
                self.create_service(
                    ManusCalibration,
                    str(
                        self.get_parameter(
                            "open_manus_calibration_service_name"
                        ).value
                    ),
                    self._on_open_manus_calibration,
                    callback_group=self._cb_group,
                ),
                self.create_service(
                    ManusCalibration,
                    str(
                        self.get_parameter(
                            "fist_manus_calibration_service_name"
                        ).value
                    ),
                    self._on_fist_manus_calibration,
                    callback_group=self._cb_group,
                ),
                self.create_service(
                    ManusCalibration,
                    str(
                        self.get_parameter(
                            "clear_manus_calibration_service_name"
                        ).value
                    ),
                    self._on_clear_manus_calibration,
                    callback_group=self._cb_group,
                ),
            ]
            self._theta_calibration_client = self.create_client(
                CalibrateGloveTheta,
                str(
                    self.get_parameter("manus_theta_calibration_service_name").value
                ),
                callback_group=self._cb_group,
            )
            self._clear_theta_calibration_client = self.create_client(
                ClearGloveThetaCalibration,
                str(
                    self.get_parameter(
                        "clear_manus_theta_calibration_service_name"
                    ).value
                ),
                callback_group=self._cb_group,
            )
            self._fist_calibration_client = self.create_client(
                RecordGloveFistCalibration,
                str(
                    self.get_parameter(
                        "record_manus_fist_calibration_service_name"
                    ).value
                ),
                callback_group=self._cb_group,
            )
        else:
            self.get_logger().warn(
                "MANUS calibration interfaces unavailable; services disabled."
            )
        # Do not gate teleop on get_connection_info; keep param for CLI compat only.
        self._conn_client = None
        poll = float(self.get_parameter("connection_poll_period_sec").value)
        self._timer = self.create_timer(
            max(poll, 0.1),
            self._on_timer,
            callback_group=self._cb_group,
        )

        # Subscribe once at init (not inside StartTeleop).
        self._subscribe_glove_activity()

        self.get_logger().info(
            f"MANUS teleop manager ready at {service_name}. "
            f"Use CODE:IP commands. {COMMAND_HELP}. "
            "Glove/retarget stay STOPPED until start. "
            "Left and right may run concurrently (one retarget process each). "
            f"Calibration services: {DEFAULT_START_CALIBRATION_SERVICE}, "
            f"{DEFAULT_OPEN_CALIBRATION_SERVICE}, "
            f"{DEFAULT_FIST_CALIBRATION_SERVICE}, "
            f"{DEFAULT_CLEAR_CALIBRATION_SERVICE}."
        )

    # --- service ---

    def _on_start_teleop(self, request, response):
        """Start: manus → wait glove topic for side → spawn retarget on that
        raw topic → arm follow. success=true only when forwarding is established.
        """
        response.success = False
        response.message = "处理中"
        self.get_logger().info(f"StartTeleop request: {request.command!r}")

        try:
            parsed = parse_teleop_command(request.command)
            if parsed.action == "unknown":
                response.message = parsed.error or (
                    f"未知命令 '{request.command}'。{COMMAND_HELP}"
                )
                return response

            assert parsed.ip is not None

            if parsed.action == "status":
                response.success = True
                response.message = self._format_status(ip=parsed.ip)
                return response

            if parsed.action == "stop":
                response.success, response.message = self._stop_session_result(
                    parsed.ip, reason="服务停止"
                )
                return response

            assert parsed.side is not None
            with self._lock:
                calibration_stage = self._state.calibration_stage.get(parsed.side)
            if calibration_stage in (CALIBRATION_WAIT_OPEN, CALIBRATION_WAIT_FIST):
                response.message = (
                    f"{parsed.side} 手正在标定({calibration_stage})，"
                    "请完成标定后再启动遥操作"
                )
                return response
            ok, msg = self._start_session_result(
                ip=parsed.ip,
                side=parsed.side,
                opposition_enabled=bool(parsed.opposition_enabled),
            )
            response.success = ok
            response.message = msg
            return response
        except Exception as exc:  # noqa: BLE001
            self.get_logger().error(f"StartTeleop 回调异常: {exc}")
            response.success = False
            response.message = f"服务异常: {exc}"
            return response

    @staticmethod
    def _init_calibration_response(response) -> None:
        response.success = False
        response.theta_rad = 0.0
        response.theta_deg = 0.0
        response.sample_count = 0
        response.message = "处理中"

    @staticmethod
    def _copy_tip_positions(source, destination) -> None:
        for source_tip, destination_tip in zip(source, destination):
            destination_tip.x = float(source_tip.x)
            destination_tip.y = float(source_tip.y)
            destination_tip.z = float(source_tip.z)

    @staticmethod
    def _request_side(request) -> str | None:
        return normalize_side(str(getattr(request, "side", "") or ""))

    def _on_start_manus_calibration(self, request, response):
        self._init_calibration_response(response)
        side = self._request_side(request)
        if side not in RETARGET_ROLES:
            response.message = "side 必须是 left 或 right"
            return response

        disarmed, detail = self._disarm_follow_publish(side)
        if not disarmed:
            response.message = f"无法关闭 {side} 机械手关节指令: {detail}"
            return response

        try:
            self._ensure_manus()
        except Exception as exc:  # noqa: BLE001
            response.message = f"启动 MANUS 失败: {exc}"
            return response

        client = self._theta_calibration_client
        if client is None or not client.wait_for_service(
            timeout_sec=self._startup_ready_timeout_sec
        ):
            response.message = (
                f"MANUS 已启动，但内部标定服务 {DEFAULT_THETA_CALIBRATION_SERVICE} "
                "未就绪"
            )
            return response

        with self._lock:
            self._state.calibration_stage[side] = CALIBRATION_WAIT_OPEN
        response.success = True
        response.message = (
            f"{side} MANUS 标定已开始，关节运动指令已关闭；"
            "请拇指自然张开四指并拢，然后调用并拢标定服务"
        )
        return response

    def _on_open_manus_calibration(self, request, response):
        self._init_calibration_response(response)
        side = self._request_side(request)
        if side not in RETARGET_ROLES:
            response.message = "side 必须是 left 或 right"
            return response

        with self._lock:
            stage = self._state.calibration_stage.get(side)
        if stage != CALIBRATION_WAIT_OPEN:
            response.message = (
                f"{side} 当前标定状态为 {stage or '未开始'}，"
                "请先调用开始标定服务"
            )
            return response

        internal, error = self._call_theta_calibration(side)
        if internal is None:
            response.message = error
            return response

        response.success = bool(internal.success)
        response.theta_rad = float(internal.theta_rad)
        response.theta_deg = float(internal.theta_deg)
        self._copy_tip_positions(
            internal.four_fingers_together_tips,
            response.four_fingers_together_tips,
        )
        response.sample_count = int(internal.sample_count)
        response.message = str(internal.message)
        if not response.success:
            return response

        with self._lock:
            self._state.calibration_stage[side] = CALIBRATION_WAIT_FIST
        response.message += "；请五指握拳，然后调用握拳标定服务"
        return response

    def _on_fist_manus_calibration(self, request, response):
        self._init_calibration_response(response)
        side = self._request_side(request)
        if side not in RETARGET_ROLES:
            response.message = "side 必须是 left 或 right"
            return response

        with self._lock:
            stage = self._state.calibration_stage.get(side)
        if stage != CALIBRATION_WAIT_FIST:
            response.message = (
                f"{side} 当前标定状态为 {stage or '未开始'}，"
                "请先完成并拢标定"
            )
            return response

        internal, error = self._call_fist_calibration(side)
        if internal is None:
            response.message = error
            return response

        response.success = bool(internal.success)
        self._copy_tip_positions(internal.fist_tips, response.fist_tips)
        response.sample_count = int(internal.sample_count)
        response.message = str(internal.message)
        if not response.success:
            return response

        with self._lock:
            self._state.calibration_stage[side] = CALIBRATION_COMPLETE
        response.message += (
            f"；{side} 握拳标定流程完成，"
            "灵巧手关节运动指令仍保持关闭，调用start_manus_teleop恢复遥操作"
        )
        return response

    def _on_clear_manus_calibration(self, request, response):
        self._init_calibration_response(response)
        side = self._request_side(request)
        if side not in RETARGET_ROLES:
            response.message = "side 必须是 left 或 right"
            return response

        disarmed, detail = self._disarm_follow_publish(side)
        if not disarmed:
            response.message = f"无法关闭 {side} 机械手关节指令: {detail}"
            return response

        try:
            self._ensure_manus()
        except Exception as exc:  # noqa: BLE001
            response.message = f"启动 MANUS 以清除标定文件失败: {exc}"
            return response

        internal, error = self._call_clear_theta_calibration(side)
        if internal is None:
            response.message = error
            return response

        response.success = bool(internal.success)
        response.theta_rad = float(internal.theta_rad)
        response.theta_deg = float(internal.theta_deg)
        self._copy_tip_positions(
            internal.four_fingers_together_tips,
            response.four_fingers_together_tips,
        )
        self._copy_tip_positions(internal.fist_tips, response.fist_tips)
        response.message = str(internal.message)
        if response.success:
            with self._lock:
                self._state.calibration_stage[side] = CALIBRATION_COMPLETE
            response.message += (
                f"；{side} 标定清除完成，"
                "灵巧手关节运动指令仍保持关闭，调用start_manus_teleop恢复遥操作"
            )
        return response

    def _call_theta_calibration(self, side: str):
        client = self._theta_calibration_client
        if client is None:
            return None, "内部 MANUS theta 标定 client 不可用"
        if not client.wait_for_service(timeout_sec=2.0):
            return None, f"内部标定服务 {DEFAULT_THETA_CALIBRATION_SERVICE} 不可用"

        request = CalibrateGloveTheta.Request()
        request.side = side
        future = client.call_async(request)
        done = threading.Event()
        future.add_done_callback(lambda _future: done.set())
        if not done.wait(timeout=5.0):
            future.cancel()
            return None, "内部 MANUS theta 标定调用超时"
        try:
            result = future.result()
        except Exception as exc:  # noqa: BLE001
            return None, f"内部 MANUS theta 标定调用失败: {exc}"
        if result is None:
            return None, "内部 MANUS theta 标定未返回结果"
        return result, ""

    def _call_clear_theta_calibration(self, side: str):
        client = self._clear_theta_calibration_client
        if client is None:
            return None, "内部 MANUS theta 清除 client 不可用"
        if not client.wait_for_service(timeout_sec=2.0):
            return None, (
                f"内部清除服务 {DEFAULT_CLEAR_THETA_CALIBRATION_SERVICE} 不可用"
            )

        request = ClearGloveThetaCalibration.Request()
        request.side = side
        future = client.call_async(request)
        done = threading.Event()
        future.add_done_callback(lambda _future: done.set())
        if not done.wait(timeout=5.0):
            future.cancel()
            return None, "内部 MANUS theta 清除调用超时"
        try:
            result = future.result()
        except Exception as exc:  # noqa: BLE001
            return None, f"内部 MANUS theta 清除调用失败: {exc}"
        if result is None:
            return None, "内部 MANUS theta 清除未返回结果"
        return result, ""

    def _call_fist_calibration(self, side: str):
        client = self._fist_calibration_client
        if client is None:
            return None, "内部 MANUS 握拳标定 client 不可用"
        if not client.wait_for_service(timeout_sec=2.0):
            return None, (
                f"内部握拳服务 {DEFAULT_RECORD_FIST_CALIBRATION_SERVICE} 不可用"
            )

        request = RecordGloveFistCalibration.Request()
        request.side = side
        future = client.call_async(request)
        done = threading.Event()
        future.add_done_callback(lambda _future: done.set())
        if not done.wait(timeout=5.0):
            future.cancel()
            return None, "内部 MANUS 握拳标定调用超时"
        try:
            result = future.result()
        except Exception as exc:  # noqa: BLE001
            return None, f"内部 MANUS 握拳标定调用失败: {exc}"
        if result is None:
            return None, "内部 MANUS 握拳标定未返回结果"
        return result, ""

    # --- lifecycle ---

    @staticmethod
    def _retarget_node_name(side: str) -> str:
        return f"manus_apex_retarget_{side}"

    def _start_session_result(
        self, *, ip: str, side: str, opposition_enabled: bool
    ) -> tuple[bool, str]:
        side = normalize_side(side) or side
        if side not in RETARGET_ROLES:
            return False, f"无效侧别: {side}"

        try:
            self._ensure_manus()
        except Exception as exc:  # noqa: BLE001
            self._rollback_start(ip, side=side)
            return False, f"拉起子进程失败: {exc}"

        # MANUS 进程登记完成后才公开会话，避免监控把尚未创建误判为退出。
        displaced: list[str] = []
        with self._lock:
            for other_ip, sess in list(self._state.sessions.items()):
                if sess.side == side and other_ip != ip:
                    self._state.sessions.pop(other_ip, None)
                    displaced.append(other_ip)
            self._state.sessions[ip] = BoundSession(
                ip=ip, side=side, opposition_enabled=opposition_enabled
            )
            self._state.no_hand_streak = 0
            # Rebinding this side: drop prior armed flag until re-armed.
            self._state.armed_sides.discard(side)
            self._sync_forwarding_locked()

        if displaced:
            self.get_logger().info(
                f"同侧覆盖: {side} 新绑定 {ip}，移除旧 IP {','.join(displaced)}"
            )

        ok, detail = self._wait_roles_healthy([ROLE_MANUS], timeout_sec=5.0)
        if not ok:
            self._rollback_start(ip, side=side)
            return False, f"启动失败: 手套子进程未保持运行。{detail}"

        ready_ok, ready_msg = self._wait_forwarding_ready(
            ip=ip,
            side=side,
            timeout_sec=self._startup_ready_timeout_sec,
            require_retarget=False,
        )
        if not ready_ok:
            self._rollback_start(ip, side=side)
            return False, ready_msg

        try:
            self._ensure_retarget(side)
        except Exception as exc:  # noqa: BLE001
            self._rollback_start(ip, side=side)
            return False, f"拉起 retarget 失败: {exc}"

        ok, detail = self._wait_roles_healthy(
            [ROLE_MANUS, side], timeout_sec=5.0
        )
        if not ok:
            self._rollback_start(ip, side=side)
            return False, (
                f"启动失败: 手套/retarget 子进程未保持运行。{detail}"
            )
        with self._lock:
            glove_topic = self._state.side_to_glove_topic.get(side, "")
        self.get_logger().info(
            f"Ready roles manus+{side} glove_topic={glove_topic!r} "
            f"(sessions={self._session_summary()}, procs={self._proc_summary()})"
        )

        if not self._arm_follow_publish(ip=ip, side=side):
            self._rollback_start(ip, side=side)
            return False, (
                "手套检测通过，但未能创建 follow 话题并放行发布"
                "（follow_publish_armed 失败）"
            )

        topic = resolve_follow_topic(ip, self._follow_topic_suffix)
        human = f"转发已建立: bound {side} -> {topic}"
        with self._lock:
            self._state.armed_sides.add(side)
            self._sync_forwarding_locked()
        return True, self._format_status(ip=ip, human=human)

    def _wait_forwarding_ready(
        self, *, ip: str, side: str, timeout_sec: float, require_retarget: bool = True
    ) -> tuple[bool, str]:
        """Wait for matching Manus glove side only (no follow topic yet).

        Follow publishers are created later when manager arms after success.
        ApexHand link state is ignored.
        When require_retarget is False (pre-spawn), only manus must stay alive.
        """
        topic = resolve_follow_topic(ip, self._follow_topic_suffix)
        topic_name = topic if topic.startswith("/") else f"/{topic}"
        side_cn = "左手" if side == "left" else "右手"
        other = "right" if side == "left" else "left"
        other_cn = "右手" if side == "left" else "左手"
        glove_window = max(self._glove_activity_timeout_sec, 2.0)
        deadline = time.time() + timeout_sec
        last_log = 0.0
        required_roles = [ROLE_MANUS, side] if require_retarget else [ROLE_MANUS]

        while time.time() < deadline:
            now = time.monotonic()
            with self._lock:
                stamp = self._state.last_glove_stamp.get(side, 0.0)
                other_stamp = self._state.last_glove_stamp.get(other, 0.0)
                saw_glove = stamp > 0.0 and (now - stamp) <= glove_window
                saw_other = other_stamp > 0.0 and (now - other_stamp) <= glove_window
                raw_side = self._state.last_raw_side
                glove_topic = self._state.side_to_glove_topic.get(side, "")
                alive = self._roles_alive_locked(required_roles)

            if not alive:
                return False, "启动失败: 手套/retarget 子进程已退出"

            if saw_glove and glove_topic:
                human = (
                    f"手套检测通过: {side_cn}/{side} topic={glove_topic} "
                    f"(将放行转发 -> {topic_name.lstrip('/')})"
                )
                self.get_logger().info(human)
                return True, human

            if now - last_log >= 2.0:
                last_log = now
                self.get_logger().info(
                    "等待手套检测: "
                    f"need_side={side} raw_side={raw_side!r} "
                    f"glove_topic={glove_topic!r} "
                    f"saw_{side}={saw_glove} saw_{other}={saw_other} "
                    "(follow 话题尚未创建)"
                )

            time.sleep(0.1)

        with self._lock:
            now = time.monotonic()
            stamp = self._state.last_glove_stamp.get(side, 0.0)
            other_stamp = self._state.last_glove_stamp.get(other, 0.0)
            saw_glove = stamp > 0.0 and (now - stamp) <= glove_window
            saw_other = other_stamp > 0.0 and (now - other_stamp) <= glove_window
            raw_side = self._state.last_raw_side
            glove_topic = self._state.side_to_glove_topic.get(side, "")

        if saw_other and not saw_glove:
            return False, (
                f"检测到{other_cn}手套数据(side={raw_side!r})，"
                f"但命令要求{side_cn}/{side}，手套选错了"
            )
        if not saw_glove:
            return False, (
                f"对应手套没有数据（需要{side_cn}/{side}），"
                "手套选错了或未佩戴/未连接"
            )
        if not glove_topic:
            return False, (
                f"已看到{side_cn}/{side}数据，但未解析到原始手套话题名"
            )
        return False, f"手套检测超时（需要{side_cn}/{side}）"

    def _retarget_node_visible(self, node_name: str) -> bool:
        """True when /{node_name} (or bare name) appears in the ROS graph."""
        fq = f"/{node_name}" if not node_name.startswith("/") else node_name
        bare = fq.lstrip("/")
        try:
            names_ns = self.get_node_names_and_namespaces()
        except Exception:  # noqa: BLE001
            return False
        for name, ns in names_ns:
            full = f"{ns.rstrip('/')}/{name}" if ns and ns != "/" else f"/{name}"
            if full == fq or name == bare:
                return True
        return False

    def _disarm_follow_publish(self, side: str) -> tuple[bool, str]:
        """Stop command publication for one retarget side before calibration."""
        with self._lock:
            proc = self._procs.get(side)
            retarget_alive = proc is not None and proc.poll() is None
            if not retarget_alive:
                self._state.armed_sides.discard(side)
                self._sync_forwarding_locked()
                return True, "retarget 未运行，无需关闭"

        node_name = self._retarget_node_name(side)
        deadline = time.monotonic() + 5.0
        while time.monotonic() < deadline:
            if self._retarget_node_visible(node_name):
                break
            time.sleep(0.1)
        else:
            return False, f"/{node_name} 不在 ROS graph 中"

        cmd = [
            "ros2",
            "param",
            "set",
            "--no-daemon",
            "--spin-time", "1.0",
            f"/{node_name}",
            "follow_publish_armed",
            "false",
        ]
        last_error = ""
        for _attempt in range(3):
            try:
                completed = subprocess.run(
                    cmd,
                    capture_output=True,
                    text=True,
                    timeout=5.0,
                    check=False,
                )
            except Exception as exc:  # noqa: BLE001
                last_error = str(exc)
                time.sleep(0.2)
                continue
            if completed.returncode == 0:
                with self._lock:
                    self._state.armed_sides.discard(side)
                    self._sync_forwarding_locked()
                self.get_logger().info(
                    f"Follow publish disarmed for {side} before MANUS calibration"
                )
                return True, "已关闭"
            last_error = (completed.stderr or completed.stdout or "").strip()
            time.sleep(0.2)
        return False, last_error or "设置 follow_publish_armed=false 失败"

    def _arm_follow_publish(self, *, ip: str, side: str) -> bool:
        """After glove checks pass: arm that side's retarget follow publishers.

        Retarget may take seconds to finish MuJoCo init (especially with viewer),
        so wait for the node to appear, then use direct discovery for parameter
        calls. A daemon started with different ROS_LOCALHOST_ONLY may have a stale graph.
        """
        node_name = self._retarget_node_name(side)
        fq_node = f"/{node_name}"
        discover_deadline = time.time() + max(20.0, self._startup_ready_timeout_sec)
        last_log = 0.0
        while time.time() < discover_deadline:
            if self._retarget_node_visible(node_name):
                break
            with self._lock:
                alive = self._roles_alive_locked([ROLE_MANUS, side])
            if not alive:
                self.get_logger().error(
                    f"arm aborted: retarget process for {side} exited before node ready"
                )
                return False
            now = time.monotonic()
            if now - last_log >= 2.0:
                last_log = now
                self.get_logger().info(
                    f"Waiting for retarget node {fq_node} before arming..."
                )
            time.sleep(0.2)
        else:
            self.get_logger().error(
                f"arm follow_publish_armed failed: node {fq_node} not in graph"
            )
            return False

        cmd = [
            "ros2",
            "param",
            "set",
            "--no-daemon",
            "--spin-time", "1.0",
            fq_node,
            "follow_publish_armed",
            "true",
        ]
        last_err = ""
        for attempt in range(1, 11):
            try:
                completed = subprocess.run(
                    cmd,
                    capture_output=True,
                    text=True,
                    timeout=5.0,
                    check=False,
                )
            except Exception as exc:  # noqa: BLE001
                last_err = str(exc)
                self.get_logger().warn(
                    f"arm follow_publish_armed attempt {attempt}/10 failed: {exc}"
                )
                time.sleep(0.3)
                continue
            if completed.returncode == 0:
                last_err = ""
                break
            last_err = (completed.stderr or completed.stdout or "").strip()
            self.get_logger().warn(
                f"arm follow_publish_armed attempt {attempt}/10: {last_err}"
            )
            time.sleep(0.4)
        else:
            self.get_logger().error(
                f"arm follow_publish_armed failed after retries: {last_err}"
            )
            return False

        topic = resolve_follow_topic(ip, self._follow_topic_suffix)
        topic_name = topic if topic.startswith("/") else f"/{topic}"
        deadline = time.time() + 10.0
        while time.time() < deadline:
            try:
                pubs = self.get_publishers_info_by_topic(topic_name)
            except Exception:  # noqa: BLE001
                pubs = []
            if pubs:
                self.get_logger().info(
                    f"Follow publish armed — topic live: {topic_name.lstrip('/')} "
                    f"(side={side}, node={fq_node})"
                )
                return True
            time.sleep(0.05)

        self.get_logger().error(
            f"follow_publish_armed set on {fq_node}, but publisher missing on "
            f"{topic_name.lstrip('/')}"
        )
        return False

    def _stop_session_result(self, ip: str, *, reason: str) -> tuple[bool, str]:
        self._stop_session(ip, reason=reason)
        return True, self._format_status(ip=ip, human=f"已停止 IP={ip}")

    def _rollback_start(self, ip: str, *, side: str | None = None) -> None:
        with self._lock:
            removed = self._state.sessions.pop(ip, None)
            kill_side = side or (removed.side if removed else None)
            if kill_side:
                self._state.armed_sides.discard(kill_side)
            remaining = len(self._state.sessions)
            self._sync_forwarding_locked()
            if remaining == 0:
                procs = dict(self._procs)
                self._procs.clear()
                self._retarget_spawn_key.clear()
                self._state.forwarding = False
                self._state.glove_mode = "none"
                self._state.last_glove_stamp.clear()
                self._state.no_hand_streak = 0
                self._state.connected_ips.clear()
                self._state.armed_sides.clear()
                self._clear_calibration_state_locked()
            else:
                procs = {}
                if kill_side and kill_side in self._procs:
                    procs[kill_side] = self._procs.pop(kill_side)
                    self._retarget_spawn_key.pop(kill_side, None)

        if remaining == 0:
            self.get_logger().info(
                f"MANUS teleop pipeline stopped: 启动失败回滚 IP={ip}"
            )
            self._kill_process_list(list(procs.values()))
            return

        if procs:
            self.get_logger().info(
                f"启动失败回滚 IP={ip} side={kill_side}; "
                f"保留其余 sessions={self._session_summary()}"
            )
            self._kill_process_list(list(procs.values()))

    def _wait_roles_healthy(
        self, roles: list[str], *, timeout_sec: float
    ) -> tuple[bool, str]:
        deadline = time.time() + timeout_sec
        last_detail = ""
        while time.time() < deadline:
            manus_node_visible = self._retarget_node_visible("manus_data_publisher")
            with self._lock:
                self._prune_dead_procs_locked()
                statuses = []
                all_ok = True
                for role in roles:
                    proc = self._procs.get(role)
                    external_manus_ok = (
                        role == ROLE_MANUS
                        and self._state.external_manus
                        and manus_node_visible
                    )
                    if external_manus_ok:
                        statuses.append("manus:external")
                    elif proc is None or proc.poll() is not None:
                        statuses.append(f"{role}:dead")
                        all_ok = False
                    else:
                        statuses.append(f"{role}:pid={proc.pid}")
                last_detail = "; ".join(statuses)
                if all_ok:
                    return True, last_detail
            time.sleep(0.1)
        manus_node_visible = self._retarget_node_visible("manus_data_publisher")
        with self._lock:
            n_ok = 0
            for role in roles:
                proc = self._procs.get(role)
                if proc is not None and proc.poll() is None:
                    n_ok += 1
                elif (
                    role == ROLE_MANUS
                    and self._state.external_manus
                    and manus_node_visible
                ):
                    n_ok += 1
        return False, f"超时后仍存活 {n_ok}/{len(roles)}；{last_detail}"

    def _start_session(
        self, *, ip: str, side: str, opposition_enabled: bool
    ) -> None:
        ok, msg = self._start_session_result(
            ip=ip, side=side, opposition_enabled=opposition_enabled
        )
        if not ok:
            raise RuntimeError(msg)

    def _stop_session(self, ip: str, *, reason: str) -> None:
        with self._lock:
            removed = self._state.sessions.pop(ip, None)
            remaining = len(self._state.sessions)
            kill_side = removed.side if removed else None
            if kill_side:
                self._state.armed_sides.discard(kill_side)
            if remaining == 0:
                procs = dict(self._procs)
                self._procs.clear()
                self._retarget_spawn_key.clear()
                self._state.forwarding = False
                self._state.glove_mode = "none"
                self._state.last_glove_stamp.clear()
                self._state.no_hand_streak = 0
                self._state.connected_ips.clear()
                self._state.armed_sides.clear()
                self._clear_calibration_state_locked()
            else:
                procs = {}
                if kill_side and kill_side in self._procs:
                    procs[kill_side] = self._procs.pop(kill_side)
                    self._retarget_spawn_key.pop(kill_side, None)
                self._sync_forwarding_locked()

        if remaining == 0:
            self.get_logger().info(
                f"MANUS teleop pipeline stopped: {reason} (last IP={ip})"
            )
            self._kill_process_list(list(procs.values()))
            return
        if removed is None:
            self.get_logger().info(f"停止请求 IP={ip}（未绑定）: {reason}")
            return
        self._kill_process_list(list(procs.values()))
        self.get_logger().info(
            f"Unbound IP={ip} side={removed.side}; remaining={self._session_summary()}"
        )

    def _stop_pipeline(self, reason: str) -> None:
        with self._lock:
            procs = dict(self._procs)
            self._procs.clear()
            self._retarget_spawn_key.clear()
            self._state.sessions.clear()
            self._state.forwarding = False
            self._state.glove_mode = "none"
            self._state.last_glove_stamp.clear()
            self._state.no_hand_streak = 0
            self._state.connected_ips.clear()
            self._state.armed_sides.clear()
            self._clear_calibration_state_locked()
        self.get_logger().info(f"MANUS teleop pipeline stopped: {reason}")
        self._kill_process_list(list(procs.values()))

    def _stop_pipeline_locked(self, reason: str) -> None:
        """Caller must hold ``_lock``. Kill wait is deferred so lock is not held."""
        procs = dict(self._procs)
        self._procs.clear()
        self._retarget_spawn_key.clear()
        self._state.sessions.clear()
        self._state.forwarding = False
        self._state.glove_mode = "none"
        self._state.last_glove_stamp.clear()
        self._state.no_hand_streak = 0
        self._state.connected_ips.clear()
        self._state.armed_sides.clear()
        self._clear_calibration_state_locked()
        self.get_logger().info(f"MANUS teleop pipeline stopped: {reason}")
        threading.Thread(
            target=self._kill_process_list,
            args=(list(procs.values()),),
            daemon=True,
        ).start()

    def _sync_forwarding_locked(self) -> None:
        self._state.forwarding = bool(self._state.armed_sides)

    def _clear_calibration_state_locked(self) -> None:
        self._state.calibration_stage.clear()
        self._state.external_manus = False

    def _session_summary(self) -> str:
        with self._lock:
            if not self._state.sessions:
                return "(none)"
            return ",".join(
                f"{s.side}->{s.ip}" for s in self._state.sessions.values()
            )

    def _proc_summary(self) -> str:
        with self._lock:
            if not self._procs:
                return "(none)"
            parts = []
            for role, proc in self._procs.items():
                if proc.poll() is None:
                    parts.append(f"{role}:{proc.pid}")
                else:
                    parts.append(f"{role}:dead")
            return ",".join(parts)

    def _bound_sides_locked(self) -> set[str]:
        return {s.side for s in self._state.sessions.values()}

    def _exo_mode_locked(self) -> str:
        sides = self._bound_sides_locked()
        if sides == {ROLE_LEFT, ROLE_RIGHT}:
            return "both"
        if ROLE_LEFT in sides:
            return ROLE_LEFT
        if ROLE_RIGHT in sides:
            return ROLE_RIGHT
        return "none"

    @staticmethod
    def _append_param(cmd: list[str], name: str, value) -> None:
        """Append ``-p name:=value`` only when value is usable for RCL parsing.

        Empty string overrides like ``-p model_xml:=`` are rejected by rcl.
        """
        if value is None:
            return
        if isinstance(value, bool):
            cmd.extend(["-p", f"{name}:={str(value).lower()}"])
            return
        if isinstance(value, (list, tuple)):
            items = [str(v).strip() for v in value if str(v).strip()]
            if not items:
                return
            # YAML sequence form accepted by rcl param overrides.
            rendered = "[" + ", ".join(f'"{item}"' for item in items) + "]"
            cmd.extend(["-p", f"{name}:={rendered}"])
            return
        text = str(value).strip() if not isinstance(value, (int, float)) else str(value)
        if text == "":
            return
        cmd.extend(["-p", f"{name}:={text}"])

    @staticmethod
    def _default_scene_xml(hand_prefix: str) -> str:
        """Resolve packaged MuJoCo scene for the given hand side."""
        scene_name = "scene_right.xml" if hand_prefix == "right" else "scene_left.xml"
        try:
            share_dir = Path(get_package_share_directory("apex_hand_teleop"))
            packaged = share_dir / "apex_hand" / scene_name
            if packaged.exists():
                return packaged.as_posix()
        except PackageNotFoundError:
            pass
        fallback = (
            Path.cwd()
            / "src"
            / "teleopration"
            / "mink"
            / "examples"
            / "apex_hand"
            / scene_name
        )
        return fallback.as_posix()

    def _ensure_manus(self) -> None:
        with self._lock:
            self._prune_dead_procs_locked()
            proc = self._procs.get(ROLE_MANUS)
            if proc is not None and proc.poll() is None:
                self._state.external_manus = False
                return
        if self._retarget_node_visible("manus_data_publisher"):
            with self._lock:
                self._state.external_manus = True
            self.get_logger().info(
                "Reusing existing /manus_data_publisher node for calibration/teleop"
            )
            return
        self._spawn_manus()

    def _resolve_glove_topic_for_side(self, side: str) -> str:
        """Raw /manus_glove_* topic last seen for this side, or configured fallback."""
        with self._lock:
            mapped = self._state.side_to_glove_topic.get(side, "").strip()
        if mapped:
            return mapped
        primary = str(self.get_parameter("glove_topic").value).strip()
        return primary or "/manus_glove_0"

    def _ensure_retarget(self, side: str) -> None:
        with self._lock:
            session = next(
                (s for s in self._state.sessions.values() if s.side == side),
                None,
            )
            if session is None:
                return
            glove_topic = self._state.side_to_glove_topic.get(side, "").strip()
            self._prune_dead_procs_locked()
            proc = self._procs.get(side)
            alive = proc is not None and proc.poll() is None
            prev_key = self._retarget_spawn_key.get(side)
        if not glove_topic:
            glove_topic = self._resolve_glove_topic_for_side(side)
        key = (session.ip, session.opposition_enabled, glove_topic)
        reuse = alive and prev_key == key
        if reuse:
            self.get_logger().info(
                f"Reusing retarget {side} pid={proc.pid} "
                f"for {side}->{session.ip} topic={glove_topic}"
            )
            return
        if alive:
            self.get_logger().info(
                f"Restarting retarget {side} for binding change "
                f"{prev_key} -> {key}"
            )
            self._kill_role(side)
        self._spawn_retarget(session, glove_topic=glove_topic)

    def _spawn_manus(self) -> None:
        env = os.environ.copy()
        manus_cmd = [
            "ros2",
            "run",
            "manus_ros2",
            "manus_data_publisher",
            "--ros-args",
        ]
        self._append_param(
            manus_cmd, "calibration_file", self.get_parameter("calibration_file").value
        )
        self._append_param(
            manus_cmd,
            "runtime_calibration_file",
            self.get_parameter("runtime_calibration_file").value,
        )
        self._append_param(
            manus_cmd,
            "calibration_glove_id",
            self.get_parameter("calibration_glove_id").value,
        )
        self.get_logger().info(f"Spawning manus_data_publisher: {' '.join(manus_cmd)}")
        proc = subprocess.Popen(
            manus_cmd,
            env=env,
            stdout=None,
            stderr=None,
            start_new_session=True,
        )
        with self._lock:
            old = self._procs.pop(ROLE_MANUS, None)
            self._procs[ROLE_MANUS] = proc
            self._state.external_manus = False
            self._state.calibration_stage.clear()
        if old is not None:
            self._kill_process_list([old])

    def _spawn_retarget(self, session: BoundSession, *, glove_topic: str) -> None:
        side = session.side
        node_name = self._retarget_node_name(side)
        env = os.environ.copy()
        glove_topic = (glove_topic or "").strip() or self._resolve_glove_topic_for_side(
            side
        )

        with self._lock:
            n_sessions = len(self._state.sessions)

        model_xml = str(self.get_parameter("model_xml").value).strip()
        if model_xml and n_sessions > 1:
            self.get_logger().warn(
                "Ignoring global model_xml while multiple hand sides are bound; "
                f"using hand_prefix={side} default scene."
            )
            model_xml = ""
        if not model_xml:
            # Explicit path helps logs; retarget also defaults from hand_prefix.
            model_xml = self._default_scene_xml(side)

        retarget_cmd = [
            "ros2",
            "run",
            "apex_hand_teleop",
            "manus_apex_retarget",
            "--ros-args",
            "-r",
            f"__node:={node_name}",
        ]
        self._append_param(retarget_cmd, "glove_topic", glove_topic)
        self._append_param(retarget_cmd, "hand_prefix", side)
        self._append_param(retarget_cmd, "model_xml", model_xml)
        self._append_param(
            retarget_cmd, "rate_hz", float(self.get_parameter("rate_hz").value)
        )
        self._append_param(
            retarget_cmd,
            "enable_viewer",
            bool(self.get_parameter("enable_viewer").value),
        )
        self._append_param(retarget_cmd, "enable_teleop_service", False)
        self._append_param(retarget_cmd, "enable_follow_routing", True)
        self._append_param(retarget_cmd, "follow_routing_auto_start", True)
        self._append_param(retarget_cmd, "follow_publish_armed", False)
        self._append_param(retarget_cmd, "no_hand_auto_stop_count", 0)
        self._append_param(retarget_cmd, "opposition_enabled", session.opposition_enabled)
        self._append_param(retarget_cmd, "bound_apexhand_ips", [session.ip])
        self._append_param(retarget_cmd, "bound_hand_sides", [side])
        self._append_param(retarget_cmd, "follow_topic_suffix", self._follow_topic_suffix)
        self._append_param(retarget_cmd, "apexhand_ip", session.ip)
        self._append_param(retarget_cmd, "publish_apexhand_commands", True)
        self._append_param(
            retarget_cmd,
            "apexhand_command_filter_window_size",
            int(self.get_parameter("apexhand_command_filter_window_size").value),
        )

        self.get_logger().info(f"Spawning {node_name}: {' '.join(retarget_cmd)}")
        proc = subprocess.Popen(
            retarget_cmd,
            env=env,
            stdout=None,
            stderr=None,
            start_new_session=True,
        )
        with self._lock:
            old = self._procs.pop(side, None)
            self._procs[side] = proc
            self._retarget_spawn_key[side] = (
                session.ip,
                session.opposition_enabled,
                glove_topic,
            )
        if old is not None:
            self._kill_process_list([old])

    def _kill_role(self, role: str) -> None:
        with self._lock:
            proc = self._procs.pop(role, None)
            if role in RETARGET_ROLES:
                self._retarget_spawn_key.pop(role, None)
                self._state.armed_sides.discard(role)
                self._sync_forwarding_locked()
        if proc is not None:
            self._kill_process_list([proc])

    def _kill_all_procs(self) -> None:
        with self._lock:
            procs = list(self._procs.values())
            self._procs.clear()
            self._retarget_spawn_key.clear()
            self._state.armed_sides.clear()
            self._clear_calibration_state_locked()
            self._sync_forwarding_locked()
        self._kill_process_list(procs)

    @staticmethod
    def _kill_process_list(children: list) -> None:
        for proc in children:
            if proc.poll() is not None:
                continue
            try:
                os.killpg(proc.pid, signal.SIGTERM)
            except ProcessLookupError:
                try:
                    proc.terminate()
                except ProcessLookupError:
                    pass
        deadline = time.time() + 5.0
        for proc in children:
            while proc.poll() is None and time.time() < deadline:
                time.sleep(0.05)
            if proc.poll() is None:
                try:
                    os.killpg(proc.pid, signal.SIGKILL)
                except ProcessLookupError:
                    try:
                        proc.kill()
                    except ProcessLookupError:
                        pass

    def _prune_dead_procs_locked(self) -> None:
        dead = [role for role, proc in self._procs.items() if proc.poll() is not None]
        for role in dead:
            self._procs.pop(role, None)
            if role in RETARGET_ROLES:
                self._retarget_spawn_key.pop(role, None)

    def _roles_alive_locked(self, roles: list[str]) -> bool:
        self._prune_dead_procs_locked()
        for role in roles:
            if role == ROLE_MANUS and self._state.external_manus:
                continue
            proc = self._procs.get(role)
            if proc is None or proc.poll() is not None:
                return False
        return True

    def _session_roles_alive_locked(self) -> bool:
        """True when manus and every bound side's retarget are alive."""
        if not self._state.sessions:
            return False
        roles = [ROLE_MANUS, *sorted(self._bound_sides_locked())]
        return self._roles_alive_locked(roles)

    # --- glove activity (only while pipeline active) ---

    def _subscribe_glove_activity(self) -> None:
        if self._activity_subs:
            return
        if ManusGlove is None:
            self.get_logger().error(
                "manus_ros2_msgs 不可用，无法检测手套 side，StartTeleop 可能误报"
            )
            return
        topics = [
            str(t).strip()
            for t in self.get_parameter("glove_activity_topics").value
            if str(t).strip()
        ]
        primary = str(self.get_parameter("glove_topic").value).strip()
        if primary and primary not in topics:
            topics.append(primary)
        # Match manus publisher / retarget (reliable depth), not BEST_EFFORT sensor.
        qos = 20
        for topic in topics:
            # Bind source topic so we can pass the raw name to retarget (no demux).
            sub = self.create_subscription(
                ManusGlove,
                topic,
                self._make_glove_activity_cb(topic),
                qos,
                callback_group=self._cb_group,
            )
            self._activity_subs.append(sub)
        self.get_logger().info(
            "Glove activity topics: "
            + (", ".join(topics) if topics else "(none)")
            + "; no demux (retarget gets raw topic at spawn)"
        )

    def _make_glove_activity_cb(self, source_topic: str):
        def _cb(msg) -> None:
            self._on_glove_activity(msg, source_topic=source_topic)

        return _cb

    def _on_glove_activity(self, msg, *, source_topic: str) -> None:
        raw = str(getattr(msg, "side", "") or "")
        side = normalize_side(raw)
        now = time.monotonic()
        with self._lock:
            self._state.last_raw_side = raw
            # Always record (incl. during StartTeleop wait) so missing-glove checks work.
            if side is not None:
                self._state.last_glove_stamp[side] = now
                self._state.side_to_glove_topic[side] = source_topic
                if self._state.active:
                    self._refresh_glove_mode_locked(now)

    def _refresh_glove_mode_locked(self, now: float) -> None:
        timeout = self._glove_activity_timeout_sec
        left = (now - self._state.last_glove_stamp.get("left", 0.0)) <= timeout
        right = (now - self._state.last_glove_stamp.get("right", 0.0)) <= timeout
        if left and right:
            self._state.glove_mode = "both"
        elif left:
            self._state.glove_mode = "left"
        elif right:
            self._state.glove_mode = "right"
        else:
            self._state.glove_mode = "none"

    # --- timer: child health only (no get_connection_info gating) ---

    def _on_timer(self) -> None:
        manus_node_visible = self._retarget_node_visible("manus_data_publisher")
        with self._lock:
            if not self._state.active and not self._state.calibration_stage:
                return
            self._prune_dead_procs_locked()

            manus = self._procs.get(ROLE_MANUS)
            manus_alive = manus is not None and manus.poll() is None
            if self._state.external_manus:
                manus_alive = manus_node_visible
            if not manus_alive:
                self._stop_pipeline_locked(reason="manus 子进程已退出")
                return

            # Calibration may run with only manus_data_publisher and no retarget.
            if not self._state.sessions:
                self._refresh_glove_mode_locked(time.monotonic())
                return

            dead_ips: list[tuple[str, str]] = []
            for ip, session in list(self._state.sessions.items()):
                proc = self._procs.get(session.side)
                # None = not spawned yet (waiting for glove topic). Do not
                # treat that as a crash or the pre-spawn wait gets rolled back.
                if proc is None:
                    continue
                if proc.poll() is not None:
                    dead_ips.append((ip, session.side))

            for ip, side in dead_ips:
                self._state.sessions.pop(ip, None)
                self._state.armed_sides.discard(side)
                self._retarget_spawn_key.pop(side, None)
                self.get_logger().warn(
                    f"retarget {side} 已退出，解绑 IP={ip}"
                )

            if not self._state.sessions:
                self._stop_pipeline_locked(reason="所有 retarget 已退出")
                return

            self._sync_forwarding_locked()
            self._refresh_glove_mode_locked(time.monotonic())

    def _format_status(
        self, human: str | None = None, *, ip: str | None = None
    ) -> str:
        with self._lock:
            sessions = dict(self._state.sessions)
            exo_mode = self._exo_mode_locked()
            glove_mode = self._state.glove_mode
            armed = set(self._state.armed_sides)
            manus_ok = self._roles_alive_locked([ROLE_MANUS]) if sessions else False

            if ip is not None:
                session = sessions.get(ip)
                side = session.side if session else "none"
                side_alive = (
                    session is not None
                    and manus_ok
                    and self._roles_alive_locked([session.side])
                )
                bound = session is not None and side_alive
                opp = (
                    ("含对指" if session.opposition_enabled else "无对指")
                    if session
                    else "-"
                )
                ip_forwarding = bound and side in armed
                if human is None:
                    if session is None:
                        human = f"IP={ip} 未绑定"
                    elif not side_alive:
                        human = f"IP={ip} 已绑定但流水线未运行"
                    elif not ip_forwarding:
                        human = f"IP={ip} 已绑定 side={side}({opp})，等待转发"
                    else:
                        human = f"IP={ip} 遥操作中 side={side}({opp})"
                return (
                    f"active={'true' if bound else 'false'} "
                    f"forwarding={'true' if ip_forwarding else 'false'} "
                    f"exo_mode={side}; {human}"
                )

            pipeline_ok = self._session_roles_alive_locked()
            active = bool(sessions) and pipeline_ok
            forwarding = bool(armed) and pipeline_ok
            if human is None:
                if not active:
                    human = "遥操作未启动"
                elif not forwarding:
                    binds = ",".join(f"{s.side}->{s.ip}" for s in sessions.values())
                    human = f"遥操作运行中，等待转发 [{binds}]"
                else:
                    binds = ",".join(f"{s.side}->{s.ip}" for s in sessions.values())
                    human = f"遥操作运行中，转发已建立 [{binds}]"
            return (
                f"active={'true' if active else 'false'} "
                f"forwarding={'true' if forwarding else 'false'} "
                f"exo_mode={exo_mode if sessions else glove_mode}; {human}"
            )

    def destroy_node(self) -> bool:
        self._stop_pipeline(reason="manager 退出")
        return super().destroy_node()


def main(args: list[str] | None = None) -> None:
    rclpy.init(args=args)
    node = ManusTeleopManager()
    # Enough threads so glove activity callbacks run while StartTeleop waits.
    executor = MultiThreadedExecutor(num_threads=4)
    executor.add_node(node)
    try:
        executor.spin()
    except KeyboardInterrupt:
        pass
    finally:
        executor.shutdown()
        node.destroy_node()
        if rclpy.ok():
            rclpy.shutdown()


if __name__ == "__main__":
    main()
